'use client';

import { useState, useEffect } from 'react';

const API_URL = '';

export default function LateBanner() {
  const [text, setText] = useState<string>('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(`${API_URL}/api/late-banner`)
      .then(r => r.json())
      .then(data => {
        setText(data.text);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, []);

  if (!loading && !text) return null;

  return (
    <div
      data-testid="late-banner"
      className={`bg-[#ff6b35] text-white py-32 px-4 text-center font-bold text-[28px]${loading ? ' animate-pulse' : ''}`}
    >
      {loading ? '\u00A0' : text}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';

const API_URL = '';

export default function SidePane() {
  const [data, setData] = useState<any>(null);

  useEffect(() => {
    fetch(`${API_URL}/api/side-pane`)
      .then(r => r.json())
      .then(setData);
  }, []);

  return (
    <aside
      data-testid="side-pane"
      className="w-[220px] shrink-0 bg-[var(--card-bg)] p-5 border-r" style={{ borderColor: 'var(--border-color)' }}
    >
      {data ? (
        <nav>
          <h3 className="mb-3 text-base font-semibold" style={{ color: 'var(--text-muted)' }}>Categories</h3>
          <ul className="list-none mb-6">
            {data.categories.map((cat: any) => (
              <li key={cat.name} className="mb-2">
                <a href={cat.href} className="text-[#0070f3] no-underline hover:underline">{cat.name}</a>
              </li>
            ))}
          </ul>
          <h3 className="mb-3 text-base font-semibold" style={{ color: 'var(--text-muted)' }}>Filters</h3>
          <ul className="list-none mb-6">
            {data.filters.map((filter: any) => (
              <li key={filter.name} className="mb-2">
                <a href={filter.href} className="text-[#0070f3] no-underline hover:underline">{filter.name}</a>
              </li>
            ))}
          </ul>
        </nav>
      ) : (
        <div className="animate-pulse">
          <div className="h-4 w-24 bg-gray-300 rounded mb-3" />
          {Array.from({ length: 5 }, (_, i) => (
            <div key={i} className="h-3 w-32 bg-gray-300 rounded mb-2" />
          ))}
          <div className="h-4 w-20 bg-gray-300 rounded mb-3 mt-6" />
          {Array.from({ length: 4 }, (_, i) => (
            <div key={i} className="h-3 w-28 bg-gray-300 rounded mb-2" />
          ))}
        </div>
      )}
    </aside>
  );
}

